    public void DeepSeekChatResponse_Deserialize_ReturnsValidObject()
    {
        var json = @"{
            ""id"": ""chatcmpl-123"",
            ""choices"": [
                {
                    ""index"": 0,
                    ""message"": {
                        ""role"": ""assistant"",
                        ""content"": ""Hello, World!""
                    },
                    ""finish_reason"": ""stop""
                }
            ],
            ""usage"": {
                ""prompt_tokens"": 10,
                ""completion_tokens"": 5,
